import { Metadata } from "next";
import { getNewsBySlug } from "@/actions/news";
import { notFound } from "next/navigation";
import Link from "next/link";
import { auth } from "@clerk/nextjs/server";
import { db } from "@/lib/db";
import { users } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import { ArrowLeft, Calendar, Eye, UserRound } from "lucide-react";

import CommentsSection from "@/components/dashboard/news/comments-section";
import ArticleContent from "@/components/news/article-content";

function stripHtml(html: string) {
  return html.replace(/<[^>]*>?/gm, "").substring(0, 160) + "...";
}

export async function generateMetadata(props: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const params = await props.params;
  const slug = decodeURIComponent(params.slug);
  const article = await getNewsBySlug(slug);

  if (!article) return { title: "Новость не найдена" };

  const baseUrl =
    process.env.NEXT_PUBLIC_APP_URL || "https://menorah-rishon.com";
  return {
    title: article.title,
    description: stripHtml(article.content),
    openGraph: {
      images: [{ url: article.imageUrl || `${baseUrl}/og-default.jpg` }],
    },
  };
}

export default async function NewsArticlePage(props: {
  params: Promise<{ slug: string }>;
}) {
  const params = await props.params;
  const slug = decodeURIComponent(params.slug);
  const { userId } = await auth();

  const article = await getNewsBySlug(slug);
  if (!article) return notFound();

  let currentUser = null;
  if (userId) {
    currentUser = await db.query.users.findFirst({
      where: eq(users.id, userId),
    });
  }

  const formattedDate = new Date(article.createdAt).toLocaleDateString(
    "ru-RU",
    {
      day: "numeric",
      month: "long",
      year: "numeric",
    },
  );

  return (
    <main className="min-h-screen bg-white dark:bg-neutral-950 pt-24 md:pt-32 pb-20 relative overflow-x-hidden">
      {/* Сетка фона */}
      <div className="absolute inset-0 h-full w-full bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:40px_40px] [mask-image:radial-gradient(ellipse_50%_50%_at_50%_0%,#000_70%,transparent_100%)] pointer-events-none" />

      <div className="relative z-10 max-w-5xl mx-auto px-4 md:px-8">
        <Link
          href="/news"
          className="inline-flex items-center gap-2 text-neutral-500 hover:text-neutral-900 dark:hover:text-white font-bold transition-colors mb-10 md:mb-16 group"
        >
          <ArrowLeft
            size={18}
            className="group-hover:-translate-x-1 transition-transform"
          />
          Ко всем новостям
        </Link>

        <header className="mb-12 md:mb-16">
          <h1 className="text-3xl md:text-5xl lg:text-7xl font-black text-neutral-900 dark:text-white tracking-tighter leading-[1.05] mb-8">
            {article.title}
          </h1>

          <div className="flex flex-wrap items-center gap-6 text-[10px] md:text-xs font-bold text-neutral-400 uppercase tracking-widest mb-8">
            <span className="flex items-center gap-2 bg-neutral-50 dark:bg-neutral-900 px-4 py-2 rounded-full">
              <Calendar size={14} className="text-[#FFB800]" /> {formattedDate}
            </span>
            <span className="flex items-center gap-2 bg-neutral-50 dark:bg-neutral-900 px-4 py-2 rounded-full">
              <Eye size={14} className="text-[#FFB800]" /> {article.views}{" "}
              Просмотров
            </span>
          </div>

          {/* 🔥 БЛОК АВТОРА */}
          {article.author && (
            <div className="mt-8">
              {article.author.authorProfile ? (
                <Link
                  href={`/authors/${article.author.authorProfile.slug}`}
                  className="inline-flex items-center gap-4 p-2 pr-6 bg-neutral-50 dark:bg-neutral-900/50 rounded-full border border-neutral-200 dark:border-neutral-800 hover:border-[#FFB800]/50 transition-colors group"
                >
                  <div className="w-12 h-12 rounded-full overflow-hidden bg-neutral-200 dark:bg-neutral-800 shrink-0">
                    {article.author.imageUrl ? (
                      <img
                        src={article.author.imageUrl}
                        alt="Автор"
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <UserRound className="w-full h-full p-3 text-neutral-400" />
                    )}
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-neutral-400 mb-0.5">
                      Лектор общины
                    </p>
                    <p className="text-sm font-bold text-neutral-900 dark:text-white group-hover:text-[#FFB800] transition-colors">
                      {article.author.firstName} {article.author.lastName}
                    </p>
                  </div>
                </Link>
              ) : (
                <div className="inline-flex items-center gap-4 p-2 pr-6 bg-neutral-50 dark:bg-neutral-900/50 rounded-full border border-neutral-200 dark:border-neutral-800">
                  <div className="w-12 h-12 rounded-full overflow-hidden bg-neutral-200 dark:bg-neutral-800 shrink-0">
                    {article.author.imageUrl ? (
                      <img
                        src={article.author.imageUrl}
                        alt="Автор"
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <UserRound className="w-full h-full p-3 text-neutral-400" />
                    )}
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-neutral-400 mb-0.5">
                      Публикация от
                    </p>
                    <p className="text-sm font-bold text-neutral-900 dark:text-white">
                      {article.author.firstName} {article.author.lastName}
                    </p>
                  </div>
                </div>
              )}
            </div>
          )}
        </header>

        {article.imageUrl && (
          <div className="w-full aspect-video rounded-[24px] md:rounded-[48px] overflow-hidden mb-16 shadow-2xl border border-neutral-100 dark:border-neutral-800">
            <img
              src={article.imageUrl}
              alt={article.title}
              className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
            />
          </div>
        )}

        <ArticleContent content={article.content} />

        <footer className="mt-24 pt-16 border-t border-neutral-100 dark:border-neutral-800">
          <CommentsSection
            newsId={article.id}
            initialComments={article.comments}
            currentUser={currentUser}
          />
        </footer>
      </div>
    </main>
  );
}

import { auth } from "@clerk/nextjs/server";
import { db } from "@/lib/db";
import { authorProfiles } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import { redirect } from "next/navigation";
import { createProfile } from "@/actions/authors.actions";
import { getAuthorContent } from "@/actions/moderation.actions";
import AuthorProfileForm from "@/components/dashboard/AuthorProfileForm";
import AuthorContentList from "@/components/dashboard/AuthorContentList";
import { PenTool, Newspaper, Video, AlertCircle, Lock } from "lucide-react";
import Link from "next/link";

export default async function AuthorCabinetPage({
  searchParams,
}: {
  // 🔥 Обновленная типизация для Next.js 15+
  searchParams: Promise<{ tab?: string }>;
}) {
  const { userId } = await auth();
  if (!userId) redirect("/sign-in");

  // 🔥 Обязательный await для searchParams в новых версиях Next.js
  const resolvedSearchParams = await searchParams;
  const urlTab = resolvedSearchParams?.tab || "profile";

  let profile = await db.query.authorProfiles.findFirst({
    where: eq(authorProfiles.userId, userId),
    with: { user: true },
  });

  if (!profile) {
    await createProfile(userId);
    redirect("/dashboard/author-profile");
  }

  // === ПРОВЕРКА ЗАПОЛНЕННОСТИ ПРОФИЛЯ ===
  const isProfileComplete = Boolean(
    profile.shortBio && profile.shortBio.trim().length > 0,
  );

  // Если профиль не заполнен, принудительно блокируем пользователя на вкладке "profile"
  const currentTab = isProfileComplete ? urlTab : "profile";

  // Получаем контент только если профиль заполнен
  const { articles, videos } = isProfileComplete
    ? await getAuthorContent(userId)
    : { articles: [], videos: [] };

  return (
    <div className="max-w-5xl mx-auto w-full p-6">
      {/* 🔴 ПРЕДУПРЕЖДЕНИЕ, ЕСЛИ ПРОФИЛЬ НЕ ЗАПОЛНЕН */}
      {!isProfileComplete && (
        <div className="mb-6 p-4 bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-900/50 rounded-2xl flex items-start gap-3">
          <AlertCircle className="text-amber-600 mt-0.5" size={20} />
          <div>
            <h3 className="font-bold text-amber-800 dark:text-amber-500">
              Заполните профиль спикера
            </h3>
            <p className="text-sm text-amber-700 dark:text-amber-400 mt-1">
              Чтобы получить возможность публиковать статьи и видео, вам
              необходимо добавить короткую биографию.
            </p>
          </div>
        </div>
      )}

      <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          {/* ФОТОГРАФИЯ ПОЛЬЗОВАТЕЛЯ ИЛИ ЗАГЛУШКА */}
          {profile.user?.imageUrl ? (
            <img
              src={profile.user.imageUrl}
              alt="Фото профиля"
              className="w-12 h-12 rounded-2xl object-cover border border-neutral-200 dark:border-neutral-800 shadow-sm"
            />
          ) : (
            <div className="w-12 h-12 bg-amber-500/10 text-amber-500 rounded-2xl flex items-center justify-center">
              <PenTool size={24} />
            </div>
          )}
          <h1 className="text-3xl font-black">Кабинет Спикера</h1>
        </div>

        {/* НАВИГАЦИЯ ПО ВКЛАДКАМ */}
        <div className="flex bg-neutral-100 dark:bg-neutral-900 p-1 rounded-xl">
          <Link
            href="?tab=profile"
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
              currentTab === "profile"
                ? "bg-white dark:bg-neutral-800 shadow-sm text-amber-500"
                : "text-neutral-500 hover:text-neutral-900"
            }`}
          >
            Мой Профиль
          </Link>

          {isProfileComplete ? (
            <>
              <Link
                href="?tab=articles"
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${
                  currentTab === "articles"
                    ? "bg-white dark:bg-neutral-800 shadow-sm text-amber-500"
                    : "text-neutral-500 hover:text-neutral-900"
                }`}
              >
                <Newspaper size={16} /> Мои Статьи
              </Link>
              <Link
                href="?tab=videos"
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${
                  currentTab === "videos"
                    ? "bg-white dark:bg-neutral-800 shadow-sm text-amber-500"
                    : "text-neutral-500 hover:text-neutral-900"
                }`}
              >
                <Video size={16} /> Мои Видео
              </Link>
            </>
          ) : (
            <>
              {/* ЗАБЛОКИРОВАННЫЕ ВКЛАДКИ */}
              <div
                className="px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 text-neutral-400 cursor-not-allowed opacity-60"
                title="Сначала заполните профиль"
              >
                <Lock size={14} /> Мои Статьи
              </div>
              <div
                className="px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 text-neutral-400 cursor-not-allowed opacity-60"
                title="Сначала заполните профиль"
              >
                <Lock size={14} /> Мои Видео
              </div>
            </>
          )}
        </div>
      </div>

      {/* КОНТЕНТ ВКЛАДОК */}
      {currentTab === "profile" && <AuthorProfileForm initialData={profile!} />}
      {currentTab === "articles" && (
        <AuthorContentList items={articles} type="news" />
      )}
      {currentTab === "videos" && (
        <AuthorContentList items={videos} type="video" />
      )}
    </div>
  );
}

// components/authors/ContentTabs.tsx
"use client";

import { useEffect, useMemo } from "react";
import { useAuthorStore } from "@/store/useAuthorStore";
import { AnimatePresence, motion } from "framer-motion";
import { Play, Youtube, X, FileText } from "lucide-react";
import Link from "next/link";

const getYoutubeId = (url: string) => {
  if (!url) return null;
  try {
    const match = url.match(
      /(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/))([^?&/]+)/,
    );
    return match?.[1]?.length === 11 ? match[1] : null;
  } catch {
    return null;
  }
};

const getThumbnailUrl = (url: string) => {
  const id = getYoutubeId(url);
  return id ? `https://img.youtube.com/vi/${id}/hqdefault.jpg` : "";
};

export default function ContentTabs({
  articles,
  videos,
}: {
  articles: any[];
  videos: any[];
}) {
  const { activeFilter, setFilter, selectedVideo, setSelectedVideo } =
    useAuthorStore();

  useEffect(() => {
    if (!selectedVideo) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSelectedVideo(null);
    };
    window.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [selectedVideo, setSelectedVideo]);

  const selectedEmbedUrl = useMemo(() => {
    const id = selectedVideo ? getYoutubeId(selectedVideo.link) : null;
    return id
      ? `https://www.youtube.com/embed/${id}?autoplay=1&rel=0&modestbranding=1`
      : null;
  }, [selectedVideo]);

  return (
    <div className="w-full">
      {/* ФИЛЬТРЫ */}
      <div className="flex gap-6 mb-8 border-b border-neutral-200 dark:border-neutral-800 pb-4">
        {(["all", "articles", "videos"] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setFilter(tab)}
            className={`font-bold text-sm md:text-base uppercase tracking-wider transition-colors relative ${
              activeFilter === tab
                ? "text-neutral-900 dark:text-white"
                : "text-neutral-400 hover:text-neutral-600"
            }`}
          >
            {tab === "all" ? "Всё" : tab === "articles" ? "Статьи" : "Видео"}
            {activeFilter === tab && (
              <motion.div
                layoutId="authorTab"
                className="absolute -bottom-[17px] left-0 right-0 h-1 bg-[#FFB800] rounded-t-full"
              />
            )}
          </button>
        ))}
      </div>

      {/* КОНТЕНТ */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AnimatePresence mode="popLayout">
          {/* СТАТЬИ */}
          {(activeFilter === "all" || activeFilter === "articles") &&
            articles.map((article) => (
              <motion.div
                key={`art-${article.id}`}
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.9 }}
              >
                <Link
                  href={`/news/${article.slug}`}
                  className="block bg-white dark:bg-neutral-900 rounded-[2rem] border border-neutral-200/50 dark:border-neutral-800 shadow-sm overflow-hidden hover:shadow-xl hover:-translate-y-1 transition-all h-full"
                >
                  {article.imageUrl && (
                    <div className="aspect-video w-full relative overflow-hidden bg-neutral-100">
                      <img
                        src={article.imageUrl}
                        alt={article.title}
                        className="object-cover w-full h-full"
                      />
                    </div>
                  )}
                  <div className="p-6">
                    <div className="flex items-center gap-2 mb-3 text-orange-500">
                      <FileText size={16} />
                      <span className="text-xs font-bold uppercase tracking-widest">
                        Статья
                      </span>
                    </div>
                    <h3 className="text-xl font-bold text-neutral-900 dark:text-white line-clamp-2">
                      {article.title}
                    </h3>
                  </div>
                </Link>
              </motion.div>
            ))}

          {/* ВИДЕО */}
          {(activeFilter === "all" || activeFilter === "videos") &&
            videos.map((video) => {
              const videoId = getYoutubeId(video.link);
              const thumbnailUrl = getThumbnailUrl(video.link);
              return (
                <motion.button
                  key={`vid-${video.id}`}
                  onClick={() => videoId && setSelectedVideo(video)}
                  disabled={!videoId}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  className="group text-left bg-white dark:bg-neutral-900 rounded-[2rem] border border-neutral-200/50 dark:border-neutral-800 shadow-sm overflow-hidden hover:shadow-xl hover:-translate-y-1 transition-all block disabled:opacity-60"
                >
                  <div className="relative aspect-video overflow-hidden bg-neutral-200 dark:bg-neutral-800">
                    {thumbnailUrl ? (
                      <img
                        src={thumbnailUrl}
                        alt={video.title}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Youtube className="text-neutral-400" size={42} />
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/15 group-hover:bg-black/35 transition-colors flex items-center justify-center">
                      <div className="w-16 h-16 bg-white/90 backdrop-blur-md rounded-full flex items-center justify-center opacity-90 group-hover:opacity-100 scale-90 group-hover:scale-100 transition-all shadow-lg">
                        <Play
                          className="text-red-600 fill-red-600 ml-1"
                          size={24}
                        />
                      </div>
                    </div>
                  </div>
                  <div className="p-6">
                    <div className="flex items-center gap-2 mb-3 text-red-500">
                      <Youtube size={16} />
                      <span className="text-xs font-bold uppercase tracking-widest">
                        Видеоурок
                      </span>
                    </div>
                    <h3 className="text-xl font-bold text-neutral-900 dark:text-white line-clamp-2">
                      {video.title}
                    </h3>
                  </div>
                </motion.button>
              );
            })}
        </AnimatePresence>
      </div>

      {/* МОДАЛКА */}
      <AnimatePresence>
        {selectedVideo && (
          <motion.div
            className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedVideo(null)}
          >
            <motion.div
              initial={{ opacity: 0, scale: 0.94 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.94 }}
              onClick={(e) => e.stopPropagation()}
              className="w-full max-w-5xl bg-white dark:bg-neutral-950 rounded-[2rem] overflow-hidden shadow-2xl"
            >
              <div className="flex items-center justify-between p-5 border-b border-neutral-200 dark:border-neutral-800">
                <h3 className="text-lg font-black text-neutral-950 dark:text-white line-clamp-1">
                  {selectedVideo.title}
                </h3>
                <button
                  onClick={() => setSelectedVideo(null)}
                  className="w-10 h-10 rounded-full bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center hover:text-red-500 shrink-0"
                >
                  <X size={18} />
                </button>
              </div>
              <div className="aspect-video bg-black">
                {selectedEmbedUrl ? (
                  <iframe
                    src={selectedEmbedUrl}
                    className="w-full h-full"
                    allow="autoplay; fullscreen"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-white p-8">
                    Ошибка загрузки видео.
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// components/authors/ContentTabs.tsx
"use client";

import { useEffect, useMemo } from "react";
import { useAuthorStore } from "@/store/useAuthorStore";
import { AnimatePresence, motion } from "framer-motion";
import { Play, Youtube, X, FileText } from "lucide-react";
import Link from "next/link";

// Утилиты для YouTube
const getYoutubeId = (url: string) => {
  if (!url) return null;
  try {
    const match = url.match(
      /(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/))([^?&/]+)/,
    );
    return match?.[1]?.length === 11 ? match[1] : null;
  } catch {
    return null;
  }
};

const getEmbedUrl = (url: string) => {
  const videoId = getYoutubeId(url);
  if (!videoId) return null;
  return `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0&modestbranding=1`;
};

const getThumbnailUrl = (url: string) => {
  const videoId = getYoutubeId(url);
  if (!videoId) return "";
  return `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
};

interface Props {
  articles: any[];
  videos: any[];
}

export default function ContentTabs({ articles, videos }: Props) {
  const { activeFilter, setFilter, selectedVideo, setSelectedVideo } =
    useAuthorStore();

  // Логика блокировки скролла и закрытия по ESC для модалки
  useEffect(() => {
    if (!selectedVideo) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSelectedVideo(null);
    };
    window.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [selectedVideo, setSelectedVideo]);

  const selectedEmbedUrl = useMemo(() => {
    if (!selectedVideo) return null;
    return getEmbedUrl(selectedVideo.link);
  }, [selectedVideo]);

  const springTransition = { duration: 0.5 };

  return (
    <div className="w-full">
      {/* ТАБЫ */}
      <div className="flex gap-6 mb-8 border-b border-neutral-200 dark:border-neutral-800 pb-4">
        {(["all", "articles", "videos"] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setFilter(tab)}
            className={`font-bold text-sm md:text-base uppercase tracking-wider transition-colors relative ${
              activeFilter === tab
                ? "text-neutral-900 dark:text-white"
                : "text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
            }`}
          >
            {tab === "all" ? "Всё" : tab === "articles" ? "Статьи" : "Видео"}

            {/* Активная полоска */}
            {activeFilter === tab && (
              <motion.div
                layoutId="activeTab"
                className="absolute -bottom-[17px] left-0 right-0 h-1 bg-[#FFB800] rounded-t-full"
              />
            )}
          </button>
        ))}
      </div>

      {/* СЕТКА КОНТЕНТА */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AnimatePresence mode="popLayout">
          {/* РЕНДЕР СТАТЕЙ */}
          {(activeFilter === "all" || activeFilter === "articles") &&
            articles.map((article, idx) => (
              <motion.div
                key={`article-${article.id}`}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.9 }}
                transition={{ delay: idx * 0.05, ...springTransition }}
              >
                <Link
                  href={`/news/${article.slug}`}
