                </motion.tr>
              ))}
            </AnimatePresence>
          </tbody>
        </table>
      </div>
    </motion.div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useCrmStore } from "@/store/useCrmStore";
import {
  Search,
  Mail,
  MessageCircle,
  X,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Users,
  Filter,
  FilterX,
  ChevronDown,
