"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import {
  Loader2,
  Calendar,
  Plus,
  Minus,
  X,
  Coins,
  MapPin,
  Check,
  UserPlus,
  Lock,
} from "lucide-react";
import {
  registerForEvent,
  getUserFamilyData,
  checkRegistration,
} from "@/actions/event";
import { useClerk } from "@clerk/nextjs";
import dayjs from "dayjs";
